import { Injectable } from '@angular/core';
import { HttpInterceptor, HttpRequest, HttpHandler, HttpEvent, HttpErrorResponse } from '@angular/common/http';
import { Observable, throwError } from 'rxjs';
import { catchError } from 'rxjs/operators';

@Injectable()
export class AuthInterceptor implements HttpInterceptor {
  
  intercept(req: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
   
    const token = localStorage.getItem('jwt_token');
    
    if (token && this.needsAuth(req.url)) {
      const authReq = req.clone({
        headers: req.headers.set('Authorization', `Bearer ${token}`)
      });
      return next.handle(authReq).pipe(
        catchError((error: HttpErrorResponse) => {
          // Handle network errors gracefully
          if (this.isNetworkError(error)) {
            console.warn('Network error detected, request may be retried:', error.message);
            // Don't treat network errors as auth failures
            return throwError(() => error);
          }
          
          // Handle authentication errors
          if (error.status === 401 || error.status === 403) {
            console.error('Authentication error detected:', error.message);
            // Clear token and redirect on auth errors
            localStorage.removeItem('jwt_token');
            // You might want to emit an event or use a service to handle this
          }
          
          return throwError(() => error);
        })
      );
    }
    
    return next.handle(req);
  }

  private needsAuth(url: string): boolean {
    const protectedEndpoints = [
      '/api/health/upload',
      '/api/health/user/current',
      '/api/health/stats'
    ];
    
    return protectedEndpoints.some(endpoint => url.includes(endpoint));
  }

  private isNetworkError(error: HttpErrorResponse): boolean {
    // Network errors: 0 (no response), 5xx (server errors), timeout
    return error.status === 0 || 
           (error.status >= 500 && error.status < 600) ||
           error.message?.includes('timeout') ||
           error.message?.includes('Network Error') ||
           error.message?.includes('ERR_NETWORK');
  }
}
